"""Conservative source-domain provenance checks for high-stakes study guidance.

This is an allowlist of authority domains, NOT a legal-rule database.
An official domain alone does NOT prove the page is applicable, current,
or that a particular applicant is visa-eligible.
"""
from urllib.parse import urlsplit

# Selected destinations only; future changes must be reviewed against
# official institutions and mission websites, not generated by an LLM.
_AUTHORITY_DOMAINS: dict[str, tuple[str, ...]] = {
    "united kingdom": ("gov.uk",),
    "uk": ("gov.uk",),
    "germany": ("auswaertiges-amt.de", "bamf.de", "germany.info"),
    "united states": ("travel.state.gov", "uscis.gov", "studyinthestates.dhs.gov"),
    "usa": ("travel.state.gov", "uscis.gov", "studyinthestates.dhs.gov"),
    "canada": ("canada.ca",),
    "australia": ("homeaffairs.gov.au",),
    "japan": ("mofa.go.jp", "moj.go.jp"),
    "netherlands": ("ind.nl", "netherlandsworldwide.nl"),
    "france": ("france-visas.gouv.fr", "diplomatie.gouv.fr"),
    "new zealand": ("immigration.govt.nz",),
}
GOVERNMENT_TOPICS = frozenset({"visa", "embassy", "predeparture"})


class OfficialEvidenceMissing(ValueError):
    """No eligible government/mission source was available for the topic."""


def authority_domains(destination: str) -> tuple[str, ...]:
    return _AUTHORITY_DOMAINS.get(" ".join(destination.strip().casefold().split()), ())


def matches_authority(url: object, domains: tuple[str, ...]) -> bool:
    if not isinstance(url, str):
        return False
    try:
        uri = urlsplit(url)
        host = (uri.hostname or "").lower().rstrip(".")
        if uri.scheme != "https" or uri.username or uri.password:
            return False
        if uri.port not in (None, 443):
            return False
        return any(host == domain or host.endswith("." + domain) for domain in domains)
    except ValueError:
        return False


def classify_sources(topic: str, destination: str, sources: list) -> list[dict]:
    """Annotate provenance; fail closed for unsupported government evidence.

    Do not trust a claim just because it was generated with a citation.
    Exact or true subdomain matching prevents gov.uk.evil.org lookalikes.
    """
    domains = authority_domains(destination)
    if topic in GOVERNMENT_TOPICS and not domains:
        raise OfficialEvidenceMissing(
            "No curated government-domain registry for this destination yet. "
            "Official visa requirements must be checked with the relevant authority."
        )
    annotated: list[dict] = []
    for source in sources:
        value = source.model_dump(mode="json")
        value["source_type"] = (
            "official_authority_domain"
            if matches_authority(value.get("url"), domains)
            else "unverified_external_source"
        )
        annotated.append(value)
    if topic in GOVERNMENT_TOPICS and not any(
        source["source_type"] == "official_authority_domain"
        for source in annotated
    ):
        raise OfficialEvidenceMissing(
            "No official government/mission source found. "
            "Cannot provide document or visa requirements from unverified sources."
        )
    return annotated
